/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `game` (
  `game_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `desc` varchar(1000) DEFAULT NULL,
  `multiplayer` tinyint DEFAULT NULL,
  `publisher` int DEFAULT NULL,
  `release_date` datetime DEFAULT NULL,
  `system_requirements` int DEFAULT NULL,
  `price` decimal(10,2) DEFAULT NULL,
  `available` tinyint NOT NULL DEFAULT '1',
  PRIMARY KEY (`game_id`),
  UNIQUE KEY `game_id_UNIQUE` (`game_id`),
  UNIQUE KEY `name` (`name`),
  KEY `publisher_idx` (`publisher`),
  KEY `system_requirements_idx` (`system_requirements`),
  CONSTRAINT `game_publisher` FOREIGN KEY (`publisher`) REFERENCES `publisher` (`publisher_id`) ON DELETE SET NULL,
  CONSTRAINT `system_requirements` FOREIGN KEY (`system_requirements`) REFERENCES `system_requirements` (`requirements_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=104 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
