DROP TABLE IF EXISTS `game_ban`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `game_ban` (
  `ban_id` int NOT NULL AUTO_INCREMENT,
  `account` int DEFAULT NULL,
  `game` int DEFAULT NULL,
  `reason` varchar(50) DEFAULT NULL,
  `expires` datetime DEFAULT NULL,
  `started` datetime DEFAULT NULL,
  PRIMARY KEY (`ban_id`),
  UNIQUE KEY `ban_id_UNIQUE` (`ban_id`),
  KEY `account_idx` (`account`),
  KEY `game_idx` (`game`),
  CONSTRAINT `ban_account` FOREIGN KEY (`account`) REFERENCES `account` (`account_id`) ON DELETE CASCADE,
  CONSTRAINT `ban_game` FOREIGN KEY (`game`) REFERENCES `game` (`game_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
